import React from "react";

/**
 * Utility function to extract Menu children
 * @param {React.ReactNode} children - The children of the Menu component
 * @returns {Object} - An object containing the extracted children
 */
const getMenuChildren = (
  children: React.ReactNode,
): {
  trigger: React.ReactElement | null;
  content: React.ReactElement | null;
} => {
  let trigger: React.ReactElement | null = null;
  let content: React.ReactElement | null = null;

  React.Children.forEach(children, (child) => {
    if (React.isValidElement(child)) {
      const displayName = (child.type as { displayName?: string }).displayName;
      if (displayName?.includes(".Trigger")) {
        trigger = child;
      } else if (displayName?.includes(".Content")) {
        content = child;
      }
    }
  });

  return { trigger, content };
};

export { getMenuChildren };
